use super::*;

impl<'a> Codegen<'a> {
    pub(super) fn run(&mut self) {
        self.out.push_str(
            "/* Generated by mylc -- do not edit. */\n",
        );
        /* 只依赖 Mylis 运行时 ABI，不引入任何 C 标准库头 */
        self.out.push_str("#include \"mylrt.h\"\n");

        // @header 里声明的 C 头
        let mut headers: Vec<String> = Vec::new();
        for d in &self.prog.decls {
            if let Some(h) = &d.c_header {
                if h == "mylrt.h" { continue; }  /* 已作为唯一运行时 ABI 头引入 */
                if !headers.contains(h) {
                    headers.push(h.clone());
                    self.out.push_str(&format!("#include <{}>\n", h));
                }
            }
        }
        self.blank();

        // 1) class 前置声明
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind == DeclKind::Class {
                self.line(&format!("typedef struct {} {};", self.class_cname(id), self.class_cname(id)));
            }
        }
        // 1b) enum 前置声明（枚举本体 + 每个变体的载荷结构）
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind == DeclKind::Enum {
                self.line(&format!(
                    "typedef struct {} {};",
                    self.enum_cname(id),
                    self.enum_cname(id)
                ));
                for vi in 0..self.prog.decls[id].variants.len() {
                    if self.prog.decls[id].variants[vi].fields.is_empty() {
                        continue;
                    }
                    self.line(&format!(
                        "typedef struct {0} {0};",
                        self.payload_cname(id, vi)
                    ));
                }
            }
        }
        // 2) interface 前置声明
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind == DeclKind::Iface && !self.bound_only_iface(id) {
                self.line(&format!("typedef struct {} {};", self.iface_cname(id), self.iface_cname(id)));
                self.line(&format!("typedef struct {} {};", self.vt_cname(id), self.vt_cname(id)));
            }
        }
        self.blank();

        // 3) Result / Option 结构体（依赖在前）
        let insts: Vec<Type> = self.prog.insts.clone();
        for t in &insts {
            self.emit_inst_type(t);
        }
        self.blank();

        // 4) interface 的 vtable 与值结构
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Iface || self.bound_only_iface(id) {
                continue;
            }
            let iid = id;
            let members: Vec<usize> = self.prog.decls[iid].members.clone();
            let vt = self.vt_cname(iid);
            let iname = self.iface_cname(iid);
            self.line(&format!("struct {} {{", vt));
            self.ind += 1;
            self.line("myrt_i32 type_id;");
            for m in &members {
                let mid = *m;
                let ret = self.prog.decls[mid].ret.clone();
                let params = self.prog.decls[mid].params.clone();
                let mut sig = String::new();
                sig.push_str(&format!("{} (*fn_{})(void*", self.ctype(&ret), self.prog.decls[mid].name));
                for p in &params {
                    sig.push_str(&format!(", {}", self.ctype(&p.ty)));
                }
                sig.push_str(");");
                self.line(&sig);
            }
            self.ind -= 1;
            self.line("};");
            self.line(&format!("struct {} {{", iname));
            self.ind += 1;
            self.line("void* obj;");
            self.line(&format!("const {}* vt;", vt));
            self.ind -= 1;
            self.line("};");
        }
        self.blank();
        self.emit_box_helpers();
        self.blank();

        // 4b) 数组结构体（前置声明 + 定义，元素类型必须已完整）
        let arrays: Vec<Type> = self.prog.arrays.clone();
        for t in &arrays {
            if let Type::Array(_) = t {
                if !t.is_resolved() { continue; }
                let n = format!("MylA_{}", self.mangle(t));
                self.line(&format!("typedef struct {} {};", n, n));
            }
        }
        for t in &arrays {
            if let Type::Array(e) = t {
                if !t.is_resolved() { continue; }
                let n = format!("MylA_{}", self.mangle(t));
                self.line(&format!("struct {} {{ myrt_u64 len; {} items[]; }};", n, self.ctype(e)));
            }
        }
        self.blank();

        // 5) class 结构体
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Class {
                continue;
            }
            let fields: Vec<Field> = self.prog.decls[id].fields.clone();
            let cname = self.class_cname(id);
            self.line(&format!("struct {} {{", cname));
            self.ind += 1;
            let mut emitted = 0usize;
            for f in &fields {
                if f.is_static {
                    continue;
                }
                self.line(&format!("{} {};", self.ctype(&f.ty), f.name));
                emitted += 1;
            }
            if emitted == 0 {
                self.line("char _unused;");
            }
            self.ind -= 1;
            self.line("};");
        }
        self.blank();

        // 5a) enum 结构体
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Enum {
                continue;
            }
            let variants = self.prog.decls[id].variants.clone();
            let ename = self.enum_cname(id);
            self.line(&format!("struct {} {{", ename));
            self.ind += 1;
            self.line("myrt_i32 tag;");
            self.line("void* data;");
            self.ind -= 1;
            self.line("};");
            for (vi, v) in variants.iter().enumerate() {
                if v.fields.is_empty() {
                    continue;
                }
                let pname = self.payload_cname(id, vi);
                self.line(&format!("struct {} {{", pname));
                self.ind += 1;
                for (i, ft) in v.fields.iter().enumerate() {
                    self.line(&format!("{} f{};", self.ctype(ft), i));
                }
                self.ind -= 1;
                self.line("};");
            }
        }
        self.blank();

        // 5b) 静态字段定义（C 全局变量）
        let mut has_statics = false;
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Class {
                continue;
            }
            let nfields = self.prog.decls[id].fields.len();
            for i in 0..nfields {
                if !self.prog.decls[id].fields[i].is_static {
                    continue;
                }
                let ct = self.ctype(&self.prog.decls[id].fields[i].ty.clone());
                let nm = self.static_field_cname(id, i);
                self.line(&format!("static {} {};", ct, nm));
                has_statics = true;
            }
        }
        if has_statics {
            self.line("static void myl_init_statics(void);");
        }
        self.blank();

        // 6) 函数原型
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Fn {
                continue;
            }
            if self.prog.decls[id].body.is_none() {
                if let Some(owner) = self.prog.decls[id].owner {
                    if self.prog.decls[owner].kind == DeclKind::Iface && self.bound_only_iface(owner) {
                        continue;
                    }
                }
                if self.ffi_has_header(id) {
                    let ret = self.prog.decls[id].ret.clone();
                    let params = self.prog.decls[id].params.clone();
                    let mut sig = format!("static {} {}(", self.ctype(&ret), self.ffi_name(id));
                    if params.is_empty() {
                        sig.push_str("void");
                    }
                    for (i, p) in params.iter().enumerate() {
                        if i > 0 {
                            sig.push_str(", ");
                        }
                        sig.push_str(&format!("{} p_{}", self.ffi_param_ctype(&p.ty), p.name));
                    }
                    sig.push_str(");");
                    self.line(&sig);
                    continue;
                }
                // 无头文件：直接声明外部符号（类型必须与 C ABI 完全一致）
                let ret = self.prog.decls[id].ret.clone();
                let params = self.prog.decls[id].params.clone();
                let mut sig = format!("extern {} {}(", self.ctype(&ret), self.prog.decls[id].name);
                if params.is_empty() {
                    sig.push_str("void");
                }
                for (i, p) in params.iter().enumerate() {
                    if i > 0 {
                        sig.push_str(", ");
                    }
                    sig.push_str(&format!("{} {}", self.ctype(&p.ty), p.name));
                }
                sig.push_str(");");
                self.line(&sig);
                continue;
            }
            let proto = self.fn_proto(id);
            self.line(&proto);
        }
        self.blank();

        // 7) 类构造器原型
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind == DeclKind::Class {
                let proto = self.ctor_proto(id);
                self.line(&proto);
            }
        }
        self.blank();

        // 7b) enum 变体构造器原型
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Enum {
                continue;
            }
            for vi in 0..self.prog.decls[id].variants.len() {
                self.line(&self.variant_proto(id, vi));
            }
        }
        self.blank();

        // 8) interface 适配包装 + vtable 实例（必须先于函数体，供转换点引用）
        let impls: Vec<(usize, usize)> = self.all_impls();
        for (cid, iid) in &impls {
            self.emit_iface_impl(*cid, *iid);
            self.blank();
        }

        // 接口 → 接口适配：按具体实现选择目标 vtable。
        for from in 0..self.prog.decls.len() {
            if self.prog.decls[from].kind != DeclKind::Iface { continue; }
            for to in 0..self.prog.decls.len() {
                if self.prog.decls[to].kind != DeclKind::Iface || from == to { continue; }
                let poss: Vec<usize> = impls.iter()
                    .filter(|(_, i)| *i == from)
                    .map(|(c, _)| *c)
                    .filter(|c| impls.iter().any(|(c2, i2)| c2 == c && *i2 == to))
                    .collect();
                let mut uniq = poss.clone();
                uniq.sort_unstable();
                uniq.dedup();
                if uniq.is_empty() { continue; }
                let ad = self.adapter_name(from, to);
                let fi = self.iface_cname(from);
                let ti = self.iface_cname(to);
                self.line(&format!("static {} {}({} v) {{", ti, ad, fi));
                self.ind += 1;
                for cid in uniq {
                    let vf = format!("VT_{}_{}", self.ctor_name(cid), self.prog.decls[from].name);
                    let vt = format!("VT_{}_{}", self.ctor_name(cid), self.prog.decls[to].name);
                    self.line(&format!(
                        "if (v.vt == &{}) return ({}){{ v.obj, &{} }};",
                        vf, ti, vt
                    ));
                }
                self.line(&format!("return ({}){{ v.obj, 0 }};", ti));
                self.ind -= 1;
                self.line("}");
                self.blank();
            }
        }

        // 8b) 进入函数体段
        self.in_body = true;

        // 9) 全部函数体（顶层函数 + 类方法，按拓扑顺序）
        let mut order_ids: Vec<usize> = Vec::new();
        for m in &self.prog.order {
            for d in &self.prog.modules[*m].decls {
                order_ids.push(*d);
            }
        }
        // 单态化生成的 class 可能晚于 order 快照，补进来（方法由 members 段发射）。
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind == DeclKind::Class && !order_ids.contains(&id) {
                order_ids.push(id);
            }
        }
        for id in order_ids {
            if self.prog.decls[id].kind == DeclKind::Fn && self.prog.decls[id].body.is_some() {
                self.emit_fn(id);
                self.blank();
            }
            if self.prog.decls[id].kind == DeclKind::Fn && self.ffi_has_header(id) {
                self.emit_ffi_wrapper(id);
                self.blank();
            }
            for m in self.prog.decls[id].members.clone() {
                if self.prog.decls[m].body.is_some() {
                    self.emit_fn(m);
                    self.blank();
                }
            }
        }

        // 11) 类构造器
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind == DeclKind::Class {
                self.emit_ctor(id);
                self.blank();
            }
        }

        // 11a) enum 变体构造器定义
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Enum {
                continue;
            }
            for vi in 0..self.prog.decls[id].variants.len() {
                self.emit_variant_ctor(id, vi);
                self.blank();
            }
        }

        // 11b) 静态字段初始化
        self.emit_statics_init();

        // 12) main
        self.emit_main();
        self.in_body = false;

        // 13) 组装：声明段 + helper 定义 + 函数体段
        let mut final_src = std::mem::take(&mut self.out);
        let defs: Vec<String> = self.helper_defs.clone();
        if !defs.is_empty() {
            final_src.push_str("/* ---- Result/Option/字符串 内联辅助 ---- */\n");
            for d in &defs {
                final_src.push_str(d);
                final_src.push('\n');
            }
            final_src.push('\n');
        }
        final_src.push_str(&self.body);
        self.out = final_src;
    }

    pub(super) fn emit_inst_type(&mut self, t: &Type) {
        // 泛型模板里的 Option<T>/Result<T> 不能生成未实例化的 C 类型。
        if !t.is_resolved() {
            return;
        }
        let key = self.mangle(t);
        if self.emitted_insts.contains(&key) {
            return;
        }
        match t {
            Type::Result(a, b) => {
                if !a.is_value() && !matches!(**a, Type::Class(_)) {
                    // 语义层已报错
                }
                self.emit_inst_type(a);
                self.emit_inst_type(b);
            }
            Type::Option(a) => self.emit_inst_type(a),
            _ => return,
        }
        self.emitted_insts.insert(key.clone());
        match t {
            Type::Result(a, b) => {
                let name = format!("MylR_{}", key);
                let oi = matches!(&**a, Type::Iface(_));
                let ei = matches!(&**b, Type::Iface(_));
                let ot = self.ctype(a);
                let et = self.ctype(b);
                match (oi, ei) {
                    (true, true) => self.line(&format!(
                        "typedef struct {{ myrt_bool is_ok; void* ok_obj; const void* ok_vt; void* err_obj; const void* err_vt; }} {};",
                        name
                    )),
                    (true, false) => self.line(&format!(
                        "typedef struct {{ myrt_bool is_ok; void* ok_obj; const void* ok_vt; {} err; }} {};",
                        et, name
                    )),
                    (false, true) => self.line(&format!(
                        "typedef struct {{ myrt_bool is_ok; {} ok; void* err_obj; const void* err_vt; }} {};",
                        ot, name
                    )),
                    _ => self.line(&format!(
                        "typedef struct {{ myrt_bool is_ok; union {{ {} ok; {} err; }} u; }} {};",
                        ot, et, name
                    )),
                }
            }
            Type::Option(a) => {
                let name = format!("MylO_{}", key);
                if matches!(&**a, Type::Iface(_)) {
                    self.line(&format!(
                        "typedef struct {{ myrt_bool is_some; void* obj; const void* vt; }} {};",
                        name
                    ));
                } else {
                    self.line(&format!(
                        "typedef struct {{ myrt_bool is_some; union {{ {} some; }} u; }} {};",
                        self.ctype(a),
                        name
                    ));
                }
            }
            _ => {}
        }
    }

    /// @header FFI 的数组参数在 C ABI 上是元素指针，Mylis 内部是 MylA_* 结构指针。
    /// 包装器参数用 void* 承接，避免把 MylA_* 直接传给 int64_t* 造成类型错误。
    fn ffi_param_ctype(&self, t: &Type) -> String {
        match t {
            Type::Array(_) => "void*".to_string(),
            _ => self.ctype(t),
        }
    }

    pub(super) fn ffi_name(&self, id: usize) -> String {
        format!("FFI_{}_{}", self.prefix(id), self.prog.decls[id].name)
    }

    pub(super) fn ffi_has_header(&self, id: usize) -> bool {
        self.prog.decls[id].body.is_none() && self.prog.decls[id].c_header.is_some()
    }

    pub(super) fn fn_proto(&self, id: usize) -> String {
        let ret = self.prog.decls[id].ret.clone();
        let params = self.prog.decls[id].params.clone();
        let name = self.fn_cname(id);
        let exported = self.prog.decls[id].owner.is_none() && export_name(&self.prog.decls[id]).is_some();
        let inline = !exported
            && self.prog.decls[id].annots.iter().any(|a| a.name == "inline");
        let link = if exported {
            if self.export_dll { "__declspec(dllexport) " } else { "" }
        } else if inline {
            "static inline "
        } else {
            "static "
        };
        let mut sig = format!("{} {} {}(", link, self.ctype(&ret), name);
        match self.prog.decls[id].owner {
            Some(_) if self.prog.decls[id].is_static => {
                if params.is_empty() {
                    sig.push_str("void");
                }
                for (i, p) in params.iter().enumerate() {
                    if i > 0 {
                        sig.push_str(", ");
                    }
                    sig.push_str(&format!("{} p_{}", self.ctype(&p.ty), p.name));
                }
            }
            Some(owner) => {
                sig.push_str(&format!("{}* self", self.decl_cname(owner)));
                for p in &params {
                    sig.push_str(&format!(", {} p_{}", self.ctype(&p.ty), p.name));
                }
            }
            None => {
                if params.is_empty() {
                    sig.push_str("void");
                }
                for (i, p) in params.iter().enumerate() {
                    if i > 0 {
                        sig.push_str(", ");
                    }
                    sig.push_str(&format!("{} p_{}", self.ctype(&p.ty), p.name));
                }
            }
        }
        sig.push_str(");");
        sig
    }

    pub(super) fn fn_cname(&self, id: usize) -> String {
        // @export("c_name")：顶层函数导出为稳定的 C 符号名（库对外 ABI）
        if let Some(ex) = export_name(&self.prog.decls[id]) {
            if self.prog.decls[id].owner.is_none() {
                return ex;
            }
        }
        match self.prog.decls[id].owner {
            Some(owner) if self.prog.decls[id].is_static => {
                self.static_fn_cname(owner, id)
            }
            Some(owner) => format!(
                "M_{}_{}_{}",
                self.prefix(owner),
                self.prog.decls[owner].name,
                self.prog.decls[id].name
            ),
            None => format!("F_{}_{}", self.prefix(id), self.prog.decls[id].name),
        }
    }

    pub(super) fn ctor_proto(&self, cid: usize) -> String {
        let ctor = self.ctor_of(cid);
        let params = ctor
            .map(|m| self.prog.decls[m].params.clone())
            .unwrap_or_default();
        let mut sig = format!("static {0}* NEW_{1}(", self.class_cname(cid), self.ctor_name(cid));
        if params.is_empty() {
            sig.push_str("void");
        }
        for (i, p) in params.iter().enumerate() {
            if i > 0 {
                sig.push_str(", ");
            }
            sig.push_str(&format!("{} p_{}", self.ctype(&p.ty), p.name));
        }
        sig.push_str(");");
        sig
    }

    pub(super) fn static_field_cname(&self, cid: usize, idx: usize) -> String {
        format!(
            "S_{}_{}_{}",
            self.prefix(cid),
            self.prog.decls[cid].name,
            self.prog.decls[cid].fields[idx].name
        )
    }

    pub(super) fn static_fn_cname(&self, cid: usize, mid: usize) -> String {
        format!(
            "SM_{}_{}_{}",
            self.prefix(cid),
            self.prog.decls[cid].name,
            self.prog.decls[mid].name
        )
    }

    pub(super) fn ctor_name(&self, cid: usize) -> String {
        format!("{}_{}", self.prefix(cid), self.prog.decls[cid].name)
    }

    pub(super) fn ctor_of(&self, cid: usize) -> Option<usize> {
        self.prog.decls[cid]
            .members
            .iter()
            .copied()
            .find(|m| self.prog.decls[*m].is_ctor)
    }

    pub(super) fn emit_fn(&mut self, id: usize) {
        let ret = self.prog.decls[id].ret.clone();
        let params = self.prog.decls[id].params.clone();
        let name = self.fn_cname(id);
        let owner = self.prog.decls[id].owner;
        let exported = owner.is_none() && export_name(&self.prog.decls[id]).is_some();
        let inline = self.prog.decls[id]
            .annots
            .iter()
            .any(|a| a.name == "inline");
        let link = if exported {
            if self.export_dll { "__declspec(dllexport) " } else { "" }
        } else if inline {
            "static inline "
        } else {
            "static "
        };

        let mut sig = format!("{} {} {}(", link, self.ctype(&ret), name);
        match owner {
            Some(_) if self.prog.decls[id].is_static => {
                if params.is_empty() {
                    sig.push_str("void");
                }
                for (i, p) in params.iter().enumerate() {
                    if i > 0 {
                        sig.push_str(", ");
                    }
                    sig.push_str(&format!("{} p_{}", self.ctype(&p.ty), p.name));
                }
            }
            Some(owner_id) => {
                sig.push_str(&format!("{}* self", self.decl_cname(owner_id)));
                for p in &params {
                    sig.push_str(&format!(", {} p_{}", self.ctype(&p.ty), p.name));
                }
            }
            None => {
                if params.is_empty() {
                    sig.push_str("void");
                }
                for (i, p) in params.iter().enumerate() {
                    if i > 0 {
                        sig.push_str(", ");
                    }
                    sig.push_str(&format!("{} p_{}", self.ctype(&p.ty), p.name));
                }
            }
        }
        sig.push_str(") {");
        self.line(&sig);
        self.ind += 1;
        self.scopes.clear();
        self.push_scope();
        self.fn_ret = ret;
        for p in &params {
            self.declare_local(&p.name, &format!("p_{}", p.name));
        }

        let body = self.prog.decls[id].body.clone().unwrap();
        self.gen_block(&body);
        self.pop_scope();
        self.ind -= 1;
        self.line("}");
    }

    pub(super) fn emit_ffi_wrapper(&mut self, id: usize) {
        let ret = self.prog.decls[id].ret.clone();
        let params = self.prog.decls[id].params.clone();
        let sym = self.prog.decls[id].name.clone();
        let mut sig = format!("static {} {}(", self.ctype(&ret), self.ffi_name(id));
        if params.is_empty() {
            sig.push_str("void");
        }
        for (i, p) in params.iter().enumerate() {
            if i > 0 {
                sig.push_str(", ");
            }
            sig.push_str(&format!("{} p_{}", self.ffi_param_ctype(&p.ty), p.name));
        }
        sig.push_str(") {");
        self.line(&sig);
        self.ind += 1;
        let mut args: Vec<String> = Vec::new();
        for p in &params {
            let a = format!("p_{}", p.name);
            args.push(a);
        }
        let call = format!("{}({})", sym, args.join(", "));
        if ret == Type::Void {
            self.line(&format!("{};", call));
        } else {
            self.line(&format!("return {};", call));
        }
        self.ind -= 1;
        self.line("}");
    }

    pub(super) fn emit_ctor(&mut self, cid: usize) {
        let ctor = self.ctor_of(cid);
        let params = ctor
            .map(|m| self.prog.decls[m].params.clone())
            .unwrap_or_default();
        let cname = self.class_cname(cid);
        let fname = self.ctor_name(cid);
        let mut sig = format!("static {}* NEW_{}(", cname, fname);
        if params.is_empty() {
            sig.push_str("void");
        }
        for (i, p) in params.iter().enumerate() {
            if i > 0 {
                sig.push_str(", ");
            }
            sig.push_str(&format!("{} p_{}", self.ctype(&p.ty), p.name));
        }
        sig.push_str(") {");
        self.line(&sig);
        self.ind += 1;
        self.scopes.clear();
        self.push_scope();
        for p in &params {
            self.declare_local(&p.name, &format!("p_{}", p.name));
        }
        self.line(&format!("{}* self = ({0}*)myrt_alloc(sizeof({0}));", cname));
        let fields = self.prog.decls[cid].fields.clone();
        for f in &fields {
            if f.is_static {
                continue;
            }
            if let Some(init) = &f.init {
                let v = self.gen_expr(init);
                self.line(&format!("self->{} = {};", f.name, v));
                let ft = f.ty.clone();
                self.barrier_slot(&ft, &format!("&self->{}", f.name), &format!("self->{}", f.name));
            }
        }
        if let Some(mid) = ctor {
            let mut args = vec!["self".to_string()];
            for p in &params {
                args.push(format!("p_{}", p.name));
            }
            self.line(&format!("{}({});", self.fn_cname(mid), args.join(", ")));
        }
        self.line("return self;");
        self.pop_scope();
        self.ind -= 1;
        self.line("}");
    }

    pub(super) fn variant_ctor_cname(&self, eid: usize, vi: usize) -> String {
        format!(
            "NEW_{}_{}",
            self.ctor_name(eid),
            self.prog.decls[eid].variants[vi].name
        )
    }

    pub(super) fn variant_proto(&self, eid: usize, vi: usize) -> String {
        let etype = self.enum_cname(eid);
        let fields = self.prog.decls[eid].variants[vi].fields.clone();
        let mut sig = format!("static {}* {}(", etype, self.variant_ctor_cname(eid, vi));
        if fields.is_empty() {
            sig.push_str("void");
        }
        for (i, ft) in fields.iter().enumerate() {
            if i > 0 {
                sig.push_str(", ");
            }
            sig.push_str(&format!("{} v{}", self.ctype(ft), i));
        }
        sig.push_str(");");
        sig
    }

    pub(super) fn emit_variant_ctor(&mut self, eid: usize, vi: usize) {
        let etype = self.enum_cname(eid);
        let fields = self.prog.decls[eid].variants[vi].fields.clone();
        let fname = self.variant_ctor_cname(eid, vi);
        self.line(&format!("{} {{", self.variant_proto(eid, vi).trim_end_matches(';')));
        self.ind += 1;
        self.line(&format!(
            "{0}* e = ({0}*)myrt_alloc(sizeof({0}));",
            etype
        ));
        self.line(&format!("e->tag = (myrt_i32){};", vi));
        if fields.is_empty() {
            self.line("e->data = 0;");
        } else {
            let pname = self.payload_cname(eid, vi);
            self.line(&format!("{0}* p = ({0}*)myrt_alloc(sizeof({0}));", pname));
            for i in 0..fields.len() {
                self.line(&format!("p->f{} = v{};", i, i));
                let ft = fields[i].clone();
                self.barrier_slot(&ft, &format!("&p->f{}", i), &format!("p->f{}", i));
            }
            self.line("e->data = (void*)p;");
            self.line("myrt_gc_write_barrier((void*)p);");
        }
        self.line("return e;");
        self.ind -= 1;
        self.line("}");
        let _ = fname;
    }

    pub(super) fn emit_box_helpers(&mut self) {
        use super::names::{box_id, box_key};
        let prims = [
            Type::I8, Type::I16, Type::I32, Type::I64,
            Type::U8, Type::U16, Type::U32, Type::U64,
            Type::F32, Type::F64, Type::Bool, Type::Str,
        ];
        for t in &prims {
            let k = box_key(t);
            let c = self.ctype(t);
            self.line(&format!("struct MylBox_{} {{ {} v; }};", k, c));
            self.line(&format!(
                "static void* myl_box_{}({} v) {{ struct MylBox_{}* p = (struct MylBox_{}*)myrt_alloc(sizeof(struct MylBox_{})); p->v = v; return p; }}",
                k, c, k, k, k
            ));
            self.line(&format!(
                "static {} myl_unbox_{}(void* p) {{ return ((struct MylBox_{}*)p)->v; }}",
                c, k, k
            ));
            for id in 0..self.prog.decls.len() {
                if self.prog.decls[id].kind != DeclKind::Iface || !self.prog.decls[id].members.is_empty() {
                    continue;
                }
                let vt = self.vt_cname(id);
                let name = format!("VT_BOX_{}_{}_{}", k, self.prefix(id), self.prog.decls[id].name);
                self.line(&format!(
                    "static const {} {} = {{ .type_id = {} }};",
                    vt, name, box_id(t)
                ));
            }
        }
    }

    /// `Self` 接口只作 bound 协议，不生成 C 的 interface/vtable。
    fn bound_only_iface(&self, iid: usize) -> bool {
        self.prog.decls[iid].members.iter().any(|m| {
            let md = &self.prog.decls[*m];
            md.params.iter().any(|p| type_has_self(&p.ty)) || type_has_self(&md.ret)
        })
    }

    /// 判断某个具体类型是否结构化满足接口签名（与 sema 的鸭子类型检查同口径）。
    fn iface_impl_compatible(&self, cid: usize, iid: usize) -> bool {
        let sigs = &self.prog.decls[iid].members;
        // 空接口（Any）对所有具体类型都成立。
        if sigs.is_empty() {
            return true;
        }
        for sid in sigs {
            let s = &self.prog.decls[*sid];
            let found = self.prog.decls[cid]
                .members
                .iter()
                .copied()
                .find(|m| {
                    let method = &self.prog.decls[*m];
                    !method.is_ctor
                        && (method.name == s.name
                            || (s.name == "toString" && method.name == "to_string"))
                });
            let mid = match found {
                Some(mid) => mid,
                None => return false,
            };
            let m = &self.prog.decls[mid];
            if m.params.len() != s.params.len() || m.ret != s.ret {
                return false;
            }
            if m.params.iter().zip(s.params.iter()).any(|(a, b)| a.ty != b.ty) {
                return false;
            }
        }
        true
    }

    /// 所有“具体类型 × 接口”的结构化实现组合。
    /// 不能只依赖 sema 记录过的显式转换：运行期 I1→I2 的适配器需要
    /// 某个只被转成 I1 的类也拥有 I2 的 vtable。
    fn all_impls(&self) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        for cid in 0..self.prog.decls.len() {
            if !matches!(self.prog.decls[cid].kind, DeclKind::Class | DeclKind::Enum) {
                continue;
            }
            for iid in 0..self.prog.decls.len() {
                if self.prog.decls[iid].kind == DeclKind::Iface
                    && !self.bound_only_iface(iid)
                    && self.iface_impl_compatible(cid, iid)
                {
                    out.push((cid, iid));
                }
            }
        }
        out
    }

    pub(super) fn emit_iface_impl(&mut self, cid: usize, iid: usize) {
        let members: Vec<usize> = self.prog.decls[iid].members.clone();
        let vt_name = format!("VT_{}_{}", self.ctor_name(cid), self.prog.decls[iid].name);
        // 包装函数
        for (idx, mid) in members.iter().enumerate() {
            let ret = self.prog.decls[*mid].ret.clone();
            let params = self.prog.decls[*mid].params.clone();
            let mname = self.prog.decls[*mid].name.clone();
            let wname = format!("W_{}_{}_{}", self.ctor_name(cid), self.prog.decls[iid].name, idx);
            let mut sig = format!("static {} {}(", self.ctype(&ret), wname);
            sig.push_str("void* s");
            for p in &params {
                sig.push_str(&format!(", {} p_{}", self.ctype(&p.ty), p.name));
            }
            sig.push_str(") {");
            self.line(&sig);
            self.ind += 1;
            let method = self.class_method(cid, &mname);
            match method {
                Some(mid2) => {
                    let mut args = vec![format!("({}*)s", self.decl_cname(cid))];
                    for p in &params {
                        args.push(format!("p_{}", p.name));
                    }
                    let call = format!("{}({})", self.fn_cname(mid2), args.join(", "));
                    if ret == Type::Void {
                        self.line(&format!("{};", call));
                    } else {
                        self.line(&format!("return {};", call));
                    }
                }
                None => {
                    self.line("/* 不可能：鸭子类型已在 sema 校验 */");
                }
            }
            self.ind -= 1;
            self.line("}");
        }
        // vtable
        self.line(&format!("static const {} {} = {{", self.vt_cname(iid), vt_name));
        self.ind += 1;
        self.line(&format!(".type_id = {},", cid));
        for (idx, mid) in members.iter().enumerate() {
            let name = self.prog.decls[*mid].name.clone();
            let wname = format!("W_{}_{}_{}", self.ctor_name(cid), self.prog.decls[iid].name, idx);
            self.line(&format!(".fn_{} = {},", name, wname));
        }
        self.ind -= 1;
        self.line("};");
    }

    pub(super) fn class_method(&self, cid: usize, name: &str) -> Option<usize> {
        self.prog.decls[cid]
            .members
            .iter()
            .copied()
            .find(|m| self.prog.decls[*m].name == name && !self.prog.decls[*m].is_ctor)
            .or_else(|| {
                if name != "toString" {
                    return None;
                }
                self.prog.decls[cid]
                    .members
                    .iter()
                    .copied()
                    .find(|m| self.prog.decls[*m].name == "to_string" && !self.prog.decls[*m].is_ctor)
            })
    }

    pub(super) fn emit_statics_init(&mut self) {
        let mut items: Vec<(usize, usize)> = Vec::new();
        for id in 0..self.prog.decls.len() {
            if self.prog.decls[id].kind != DeclKind::Class {
                continue;
            }
            for i in 0..self.prog.decls[id].fields.len() {
                if self.prog.decls[id].fields[i].is_static {
                    items.push((id, i));
                }
            }
        }
        if items.is_empty() {
            return;
        }
        self.line("static void myl_init_statics(void) {");
        self.ind += 1;
        self.scopes.clear();
        self.push_scope();
        for (cid, idx) in items {
            let init = self.prog.decls[cid].fields[idx].init.clone();
            let target = self.static_field_cname(cid, idx);
            // 静态字段是 C 全局变量：把它的地址注册为 GC 根，避免被误回收
            self.line(&format!(
                "myrt_gc_add_root_range((void*)&{t}, sizeof({t}));",
                t = target
            ));
            let value = match init {
                Some(e) => self.gen_expr(&e),
                None => self.default_value(&self.prog.decls[cid].fields[idx].ty.clone()),
            };
            self.line(&format!("{} = {};", target, value));
            let ft = self.prog.decls[cid].fields[idx].ty.clone();
            self.barrier_slot(&ft, &format!("&{}", target), &target);
        }
        self.pop_scope();
        self.ind -= 1;
        self.line("}");

        self.blank();
    }

    pub(super) fn emit_main(&mut self) {
        let entry = self.prog.entry;
        let main_fn = self.prog.modules[entry]
            .decls
            .iter()
            .copied()
            .find(|d| {
                self.prog.decls[*d].kind == DeclKind::Fn
                    && self.prog.decls[*d].owner.is_none()
                    && self.prog.decls[*d].name == "main"
            });
        let has_statics_any = self.prog.decls.iter().any(|d| {
            d.kind == DeclKind::Class && d.fields.iter().any(|f| f.is_static)
        });
        if self.is_lib {
            let stem = self.prog.modules[entry].stem.clone();
            let attr = if self.export_dll { "__declspec(dllexport) " } else { "" };
            self.line(&format!("{}void {}_init(void) {{", attr, stem));
            self.ind += 1;
            self.line("myrt_init();");
            if has_statics_any {
                self.line("myl_init_statics();");
            }
            self.ind -= 1;
            self.line("}");
        } else {
        self.line("int main(void) {");
        self.ind += 1;
        self.line("myrt_init();");
        let has_statics = self.prog.decls.iter().any(|d| {
            d.kind == DeclKind::Class && d.fields.iter().any(|f| f.is_static)
        });
        if has_statics {
            self.line("myl_init_statics();");
        }
        match main_fn {
            Some(id) => {
                let ret = self.prog.decls[id].ret.clone();
                if ret == Type::Void {
                    self.line(&format!("{}();", self.fn_cname(id)));
                    self.line("return 0;");
                } else if ret == Type::I32 {
                    self.line(&format!("return (int){}();", self.fn_cname(id)));
                } else {
                    self.line(&format!("(void){}();", self.fn_cname(id)));
                    self.line("return 0;");
                }
            }
            None => {
                self.line("/* 入口文件缺少 pub fn main() -> i32 */");
                self.line("return 1;");
            }
        }
        self.ind -= 1;
        self.line("}");
        }
    }
}

fn type_has_self(t: &Type) -> bool {
    match t {
        Type::Named(n) => n == "Self",
        Type::Generic(_, args) => args.iter().any(type_has_self),
        Type::Ptr(e) | Type::Array(e) | Type::Option(e) => type_has_self(e),
        Type::Result(a, b) => type_has_self(a) || type_has_self(b),
        _ => false,
    }
}
